Lemma free_slot : forall b0 maps n,
  NICE b0 maps -> (forall e, In e maps -> elo e < ehi e) -> live_bytes maps + n <= LIM -> PGSZ <= n ->
  let c := cls n in
  exists i, 0 <= i < 2^(35 - c) /\
    forall e, In e maps -> ehi e <= ARENA c + i * 2^c \/ ARENA c + i * 2^c + n <= elo e.
